293	    lastError = `push rejected: ${gitError(push)}`;
294	    if (attempt < 3) await sleep(attempt * retryBackoffMs); // lost a race or a network blip — refetch and rebuild
295	  }
296	  throw new Error(`could not capture to ${branch} after 3 attempts — ${lastError}`);
297	}
