301	// Claude Code keeps session transcripts under <config>/projects/, one directory
302	// per project. CLAUDE_CONFIG_DIR relocates that config root when set (honor it so
303	// discovery follows the harness); otherwise it is ~/.claude.
304	function projectsRoot() {
