315	function newestTranscript(dir) {
316	  if (!existsSync(dir)) return null;
317	  const files = readdirSync(dir).filter((f) => f.endsWith('.jsonl'));
318	  let best = null;
319	  for (const f of files) {
320	    const path = join(dir, f);
321	    const mtime = statSync(path).mtimeMs;
322	    if (!best || mtime > best.mtime) best = { path, mtime };
323	  }
324	  return best?.path ?? null;
325	}
