327	// Locate this session's transcript. The session id names the file exactly
328	// (<sessionId>.jsonl), so search every project directory for it first — that
329	// survives the case the slug cannot: a remote/web session whose launch cwd (and
330	// thus transcript slug) differs from the git-root path this script derives, which
331	// otherwise points at a directory that never existed. Fall back to the slug
332	// directory's newest transcript, then to the newest transcript anywhere.
333	export function findTranscript({ root, sessionId, projects = projectsRoot() }) {
334	  const dirs = existsSync(projects)
335	    ? readdirSync(projects, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => join(projects, d.name))
336	    : [];
337	  if (sessionId) {
338	    for (const dir of dirs) {
339	      const hit = join(dir, `${sessionId}.jsonl`);
340	      if (existsSync(hit)) return hit;
341	    }
342	  }
343	  const bySlug = newestTranscript(join(projects, slugFor(root)));
344	  if (bySlug) return bySlug;
345	  let best = null;
346	  for (const dir of dirs) {
347	    const path = newestTranscript(dir);
348	    if (path) { const mtime = statSync(path).mtimeMs; if (!best || mtime > best.mtime) best = { path, mtime }; }
349	  }
350	  return best?.path ?? null;
351	}
