353	// Subagent sidechains: any agent-*.jsonl under the session's own directory —
354	// where the harness writes a subagent's stream (engine/checks/helpers/session-transcript.mjs
355	// states the layout). Swept at any depth, since older harnesses instead inlined
356	// sidechain entries in the main file and a mixed session must still merge whole.
357	function sidechainFiles(transcript, sessionId) {
358	  const roots = [join(dirname(transcript), sessionId)];
359	  const out = [];
360	  while (roots.length) {
361	    const dir = roots.pop();
362	    if (!existsSync(dir)) continue;
363	    for (const d of readdirSync(dir, { withFileTypes: true })) {
364	      if (d.isDirectory()) roots.push(join(dir, d.name));
365	      else if (/^agent-.*\.jsonl$/.test(d.name)) out.push(join(dir, d.name));
366	    }
367	  }
368	  return out.sort();
369	}
