     1	// What a pack's `public/` folder actually publishes, and who outside the pack reads it.
     2	//
     3	// A published surface is a promise, and a promise nobody renders drifts: this pack's
     4	// shelf carried a hand-written table of "modules other packs import" that named an
     5	// export (`landPr`) no file has ever had, claimed a folder held only named exports
     6	// while nine of its modules opened with `export *`, and listed a consumer for a module
     7	// nothing imports. None of that was visible in a diff, because the table and the code
     8	// it described were edited in different changes.
     9	//
    10	// So the table is derived instead. `renderSurfaceReport` is pure over a tree already
    11	// read into memory, which keeps the scope assertion honest — a caller that hands it an
    12	// empty file set gets an error rather than an empty report that reads as "no surface".
    13	//
    14	// A WILDCARD is reported as its own state, never expanded into a name list. `export *`
    15	// republishes whatever its target exports today, so the surface it publishes is not a
    16	// fact about this file at all; rendering the target's current names would state a
    17	// promise the folder has not made.
    18	
    19	// `export { a, b as c } from '…'` / `export { a, b }` — the named form, which is the
    20	// only form that pins a surface. `as` matters: what the outside sees is the alias.
    21	const RE_NAMED = /^export\s*\{([^}]*)\}/;
    22	const RE_STAR = /^export\s*\*\s*(?:as\s+([\w$]+)\s+)?from\s*['"]([^'"]+)['"]/;
    23	const RE_DECL = /^export\s+(?:async\s+)?(?:function\s*\*?\s*([\w$]+)|class\s+([\w$]+)|(?:const|let|var)\s+([\w$]+))/;
    24	
    25	// An `import {`/`export {` list may wrap across lines, and the path it comes from sits
    26	// on the LAST of them; fold each one back onto its opening line before matching, or a
    27	// multi-line import reads as a module consumed for no names at all.
    28	function logicalLines(text) {
    29	  const lines = text.split('\n');
    30	  const out = [];
    31	  for (let i = 0; i < lines.length; i++) {
    32	    let line = lines[i];
    33	    while (/^\s*(?:import|export)\s*\{/.test(line) && !line.includes('}') && i + 1 < lines.length) line += ' ' + lines[++i].trim();
    34	    out.push(line);
    35	  }
    36	  return out;
    37	}
    38	
    39	// The names one module publishes. `wildcards` are the `export * from` targets it
    40	// opens with; a module carrying both a star and a list publishes MORE than its list,
    41	// which is the case worth seeing in a report.
    42	export function publishedNames(text) {
    43	  const names = [];
    44	  const wildcards = [];
    45	  for (const line of logicalLines(text)) {
    46	    let m;
    47	    if ((m = line.match(RE_STAR))) {
    48	      if (m[1]) names.push(m[1]);
    49	      else wildcards.push(m[2]);
    50	    } else if ((m = line.match(RE_DECL))) {
    51	      names.push(m[1] || m[2] || m[3]);
    52	    } else if ((m = line.match(RE_NAMED))) {
    53	      for (const part of m[1].split(',')) {
    54	        const n = part.trim().match(/^([\w$]+)(?:\s+as\s+([\w$]+))?$/);
    55	        if (n) names.push(n[2] || n[1]);
    56	      }
    57	    }
    58	  }
    59	  return { names: [...new Set(names)].sort(), wildcards };
    60	}
