// Dry run of the design's `check`: parse every provenance file, verify grammar,
// and resolve every binding against the real pack. Exit 1 on any finding.
import { readFileSync, readdirSync, existsSync } from 'node:fs';
import { join } from 'node:path';

const [packDir, provDir] = process.argv.slice(2);
const KINDS = new Set(['born','reworded','strengthened','weakened','split','merged','moved','converted','trigger-changed','policy-changed','severity-changed','reaffirmed','promoted','retired']);
const findings = [];

function rulesIn(file) {
  if (!existsSync(file)) return [];
  const lines = readFileSync(file, 'utf8').split('\n');
  const bullets = []; let cur = null;
  for (const line of lines) {
    if (/^- /.test(line)) { if (cur) bullets.push(cur); cur = line.slice(2); continue; }
    if (cur !== null && /^\s+\S/.test(line)) { cur += ' ' + line.trim(); continue; }
    if (cur) { bullets.push(cur); cur = null; }
  }
  if (cur) bullets.push(cur);
  return bullets.map((b) => b.match(/^\*\*(.+?)\*\*/)?.[1]?.replace(/\s+/g, ' ')).filter(Boolean);
}
const checkIds = new Set();
for (const dir of ['worldRules', 'workRules']) {
  const d = join(packDir, dir); if (!existsSync(d)) continue;
  for (const f of readdirSync(d)) { const id = readFileSync(join(d, f), 'utf8').match(/\bid:\s*['"]([^'"]+)['"]/)?.[1]; if (id) checkIds.add(id); }
}
if (existsSync(join(packDir, 'declared-checks.json'))) for (const c of JSON.parse(readFileSync(join(packDir, 'declared-checks.json'), 'utf8'))) checkIds.add(c.id);
const skills = new Set(existsSync(join(packDir, 'skills')) ? readdirSync(join(packDir, 'skills')) : []);
const tasks = new Set(existsSync(join(packDir, 'tasks')) ? readdirSync(join(packDir, 'tasks')) : []);
const packId = packDir.split('/').filter(Boolean).pop();
const ruleCache = new Map();
const covered = new Map(); // carrier key -> file

for (const name of readdirSync(provDir).sort()) {
  const text = readFileSync(join(provDir, name), 'utf8');
  const m = text.match(/^---\n([\s\S]*?)\n---\n/);
  if (!m) { findings.push(`${name}: no header`); continue; }
  const header = m[1].split('\n');
  if (name === 'declined.md') { if (header[0] !== 'log: declined candidates') findings.push(`${name}: bad log header`); continue; }
  if (header[0] !== 'covers:') findings.push(`${name}: header must open with covers:`);
  const status = header.find((l) => /^status: /.test(l))?.slice(8);
  if (!['live', 'retired'].includes(status)) findings.push(`${name}: status must be live|retired`);
  const bindings = header.filter((l) => /^  - /.test(l)).map((l) => l.slice(4));
  if (!bindings.length) findings.push(`${name}: covers nothing`);
  for (const b of bindings) {
    const [, kind, ref] = b.match(/^(\w+): (.+)$/) ?? [];
    let ok = false;
    if (kind === 'rule') {
      const [file, trigger] = ref.split(' — ');
      if (!ruleCache.has(file)) ruleCache.set(file, rulesIn(join(packDir, file)));
      ok = ruleCache.get(file).includes(trigger);
    } else if (kind === 'check') ok = checkIds.has(ref);
    else if (kind === 'skill') ok = skills.has(ref);
    else if (kind === 'task') ok = tasks.has(ref);
    else if (kind === 'pack') ok = ref === packId;
    if (!ok) findings.push(`${name}: binding does not resolve: ${b}`);
    if (status === 'live') { if (covered.has(b)) findings.push(`${b}: covered twice (${covered.get(b)}, ${name})`); covered.set(b, name); }
  }
  const body = text.slice(m[0].length);
  const heads = [...body.matchAll(/^## (.*)$/gm)].map((x) => x[1]);
  let last = '';
  heads.forEach((h, i) => {
    const hm = h.match(/^(\d{4}-\d{2}-\d{2}) · ([a-z-]+) · (.+)$/);
    if (!hm) { findings.push(`${name}: bad entry heading: ${h}`); return; }
    if (!KINDS.has(hm[2])) findings.push(`${name}: unknown kind ${hm[2]}`);
    if (i === 0 && hm[2] !== 'born') findings.push(`${name}: first entry is ${hm[2]}, not born`);
    if (hm[1] < last) findings.push(`${name}: dates out of order at ${h}`);
    last = hm[1];
  });
  if (heads.length) {
    const born = body.split(/^## /m)[1];
    for (const f of ['Source', 'Reason', 'Actor', 'Model', 'Mechanism', 'Rejected', 'Retire when', 'Evidence'])
      if (!new RegExp(`^- \\*\\*${f}:\\*\\* `, 'm').test(born)) findings.push(`${name}: born entry lacks ${f}`);
  }
  for (const line of body.split('\n')) if (/^- \*\*/.test(line) && !/^- \*\*[A-Z][\w ]*:\*\* \S/.test(line)) findings.push(`${name}: bad field line: ${line}`);
}
// coverage: every carrier of the pack is covered exactly once
const carriers = [`pack: ${packId}`,
  ...rulesIn(join(packDir, 'RULES.md')).map((t) => `rule: RULES.md — ${t}`),
  ...[...skills].map((s) => `skill: ${s}`), ...[...checkIds].map((c) => `check: ${c}`), ...[...tasks].map((t) => `task: ${t}`)];
for (const c of carriers) if (!covered.has(c)) findings.push(`uncovered carrier: ${c}`);
for (const c of covered.keys()) if (!carriers.includes(c)) findings.push(`stale binding: ${c}`);
if (findings.length) { console.log(findings.join('\n')); process.exit(1); }
console.log(`ok: ${carriers.length} carriers covered by ${readdirSync(provDir).length - 1} element files`);
EOF
