// Dry run of the design's marking pass, marker form: render the pack's RULES.md
// with a slug marker ending every unmarked rule, and create a header-only
// provenance file for every carrier no file is named by. Files named by id
// (check/skill/task, slash -> hyphen), `pack`, or the rule's marker slug.
import { readFileSync, readdirSync, existsSync, mkdirSync, writeFileSync } from 'node:fs';
import { join, basename } from 'node:path';

const [packDir, outDir] = process.argv.slice(2);
const provDir = join(outDir, 'provenance');
mkdirSync(provDir, { recursive: true });
const LINE_MAX = 100;

// Slugs a maintainer refined from the proposals; anything else gets a proposal.
const CHOSEN = {
  'Handing a path to a Chrome API or `fetch` from an MV3 service worker': 'worker-absolute-paths',
  'Wanting `import`/`export` in extension code': 'native-es-modules',
  'Assembling a shared global from several injected content-script files': 'augment-shared-global',
  'Accumulating state in a file that is re-injected': 'reset-on-reinjection',
  'Loading ES module code into a content script': 'content-script-module-syntax',
  'Adding an import to a content-script module': 'web-accessible-import-graph',
  'Keeping that `web_accessible_resources` list correct': 'web-accessible-list-test',
  'Matching a host with `chrome.events.UrlFilter`': 'url-filter-host-operators',
  'A fetch to a host you listed failing in-browser': 'host-permissions-cors',
  'Reaching your *own* backend': 'own-backend-no-host-permission',
  'Authenticating an extension to a JWT-validating backend': 'id-token-for-jwt-backends',
  'Refreshing a token silently': 'silent-refresh-prompt-none',
  'Refreshing silently with more than one account signed in': 'silent-refresh-login-hint',
  'Storing a token': 'tokens-in-session-storage',
  'Wanting a token to survive a browser restart': 'token-across-restarts',
  'Knowing whether your side panel is open': 'side-panel-port',
  'Opening the side panel programmatically': 'side-panel-open-version',
  'Putting a menu on the toolbar icon itself': 'action-context-menu',
  'Recreating those menu items on install or startup': 'context-menus-remove-all',
  'Awaiting a `chrome.*` callback API inside `Runtime.evaluate`': 'cdp-await-plain-promises',
  'Reading a worker value from an injected evaluate': 'cdp-globalthis-exposure',
  'Attaching to a dormant worker': 'cdp-poll-dormant-worker',
};
const STOP = new Set(['a', 'an', 'the', 'to', 'of', 'in', 'on', 'with', 'from', 'your', 'that', 'those', 'or', 'and', 'for', 'into']);
const propose = (t) => t.toLowerCase().replace(/`/g, '').replace(/[^a-z0-9]+/g, ' ').trim().split(' ').filter((w) => !STOP.has(w)).slice(0, 3).join('-');
const MARKER = /\(([a-z0-9][a-z0-9-]*)\)\s*$/;

// Top-level bullets as [start, end) line ranges, with the joined text.
function bullets(lines) {
  const out = []; let cur = null;
  lines.forEach((line, i) => {
    if (/^- /.test(line)) { if (cur) out.push(cur); cur = { start: i, end: i + 1, text: line.slice(2) }; return; }
    if (cur && /^\s+\S/.test(line)) { cur.end = i + 1; cur.text += ' ' + line.trim(); return; }
    if (cur) { out.push(cur); cur = null; }
  });
  if (cur) out.push(cur);
  return out.map((b) => ({ ...b, trigger: b.text.match(/^\*\*(.+?)\*\*/)?.[1]?.replace(/\s+/g, ' ') })).filter((b) => b.trigger);
}

const elements = [{ kind: 'pack', ref: basename(packDir), slug: 'pack' }];
const rulesFile = join(packDir, 'RULES.md');
if (existsSync(rulesFile)) {
  const lines = readFileSync(rulesFile, 'utf8').split('\n');
  const marked = [...lines];
  for (const b of bullets(lines)) {
    const last = b.end - 1;
    const existing = lines[last].match(MARKER)?.[1];
    const slug = existing ?? CHOSEN[b.trigger] ?? propose(b.trigger);
    elements.push({ kind: 'rule', ref: b.trigger, slug, proposed: !existing && !CHOSEN[b.trigger] });
    if (existing) continue;
    const tag = `(${slug})`;
    marked[last] = lines[last].length + 1 + tag.length <= LINE_MAX ? `${lines[last]} ${tag}` : `${lines[last]}\n  ${tag}`;
  }
  writeFileSync(join(outDir, 'RULES.md'), marked.join('\n'));
}
const skillsDir = join(packDir, 'skills');
if (existsSync(skillsDir)) for (const s of readdirSync(skillsDir)) elements.push({ kind: 'skill', ref: s, slug: s });
for (const dir of ['worldRules', 'workRules']) {
  const d = join(packDir, dir); if (!existsSync(d)) continue;
  for (const f of readdirSync(d)) {
    if (!f.endsWith('.mjs') || f.endsWith('.test.mjs')) continue;
    const id = readFileSync(join(d, f), 'utf8').match(/\bid:\s*['"]([^'"]+)['"]/)?.[1];
    if (id) elements.push({ kind: 'check', ref: id, slug: id.replace(/\//g, '-') });
  }
}
const declared = join(packDir, 'declared-checks.json');
if (existsSync(declared)) for (const c of JSON.parse(readFileSync(declared, 'utf8'))) elements.push({ kind: 'check', ref: c.id, slug: c.id.replace(/\//g, '-') });
const tasksDir = join(packDir, 'tasks');
if (existsSync(tasksDir)) for (const t of readdirSync(tasksDir)) if (existsSync(join(tasksDir, t, 'task.json'))) elements.push({ kind: 'task', ref: t, slug: t });

let created = 0;
const byFile = new Map();
for (const e of elements) {
  byFile.set(e.slug, [...(byFile.get(e.slug) ?? []), e]);
  const file = join(provDir, `${e.slug}.md`);
  if (existsSync(file)) continue;
  writeFileSync(file, '---\nstatus: live\n---\n');
  created += 1;
}
console.log(`${elements.length} carriers, ${byFile.size} element files, ${created} created header-only`);
for (const [slug, es] of byFile) console.log(`${slug.padEnd(34)} ${es.map((e) => `${e.kind}: ${e.ref}${e.proposed ? ' (proposed slug)' : ''}`).join(' + ')}`);
EOF
