=== path-scoped-skills.mjs
// Path-scoped skills: every skill an active pack bundles that declares
// `force-load-on-file-edits-paths` under its frontmatter `metadata` (the files a
// file tool may touch only with the skill loaded), and the one question both
// readers ask of them —
// which of those skills does THIS path need that the session has not yet loaded.
// The PreToolUse hook (engine/hooks/pretooluse-command.mjs) asks it before a file
// tool runs, so the skill is loaded before the first edit exists; the
// `skill-loaded-before-editing` work rule asks it of the diff at Stop, which is what
// catches an edit the hook never saw (one made through Bash). One resolver, so the
// two cannot disagree about a pattern.
//
// Pattern grammar is the harness's (memory docs, "path-specific rules"): `**` spans
// directories, `*` and `?` stay inside one segment, `{a,b}` expands, everything
// else is literal, and a pattern is matched against the whole repo-relative path —
// so `wiki/**` is the tree and `**/packs/*/RULES.md` is that file at any depth.
import { join } from 'node:path';
import { skillMetadata } from './skill-frontmatter.mjs';

const RE_SPECIALS = /[.+^${}()|[\]\\]/g;

// `{a,b}` groups multiplied out, innermost first, so the matcher below never sees one.
export function expandBraces(glob) {
  const m = /\{([^{}]*)\}/.exec(glob);
  if (!m) return [glob];
  return m[1].split(',').flatMap((alt) => expandBraces(glob.slice(0, m.index) + alt + glob.slice(m.index + m[0].length)));
}

function oneGlobToSource(glob) {
  let re = '';
  for (let i = 0; i < glob.length; i += 1) {
    const c = glob[i];
    if (c === '*' && glob[i + 1] === '*') {
      // `**/` — zero or more whole segments; a trailing `**` — anything at all.
      if (glob[i + 2] === '/') { re += '(?:.*/)?'; i += 2; } else { re += '.*'; i += 1; }
    } else if (c === '*') re += '[^/]*';
    else if (c === '?') re += '[^/]';
    else re += c.replace(RE_SPECIALS, '\\$&');
  }
  return re;
}

export function globToRegExp(glob) {
  return new RegExp(`^(?:${expandBraces(glob).map(oneGlobToSource).join('|')})$`);
}

// The scoped skills of the given packs, flattened: [{ pack, skill, dir, files, re }], one
// entry per pattern. Callers pass the ACTIVE packs — activation is the registry's
// call, not this module's — so an undeclared pack's skills bind nothing. Read off each
// pack's own `skills` list (the convention fills it from the directory), so a skill the
// manifest withholds is not scoped either.
export function pathScopedSkills(packs) {
  const out = [];
  for (const pack of packs ?? []) {
    if (!pack.dir) continue;
    for (const skill of pack.skills ?? []) {
      const dir = join(pack.dir, 'skills', skill);
      for (const files of skillMetadata(dir).forceLoadPaths) {
        out.push({ pack: pack.id, skill, dir, files, re: globToRegExp(files) });
      }
    }
  }
  return out;
}

// The declarations `hit` admits whose skill is not among `loaded`, deduped by
// skill name — the reason to stop an action, or the empty list that lets it run.
// `loaded` may be the names or a function producing them: the function is called
// only once a declaration hits, so the transcript behind it is read only when a
// verdict actually depends on it.
function missing(declarations, loaded, hit) {
  let have = null;
  const seen = new Set();
  const out = [];
  for (const d of declarations) {
    if (!hit(d) || seen.has(d.skill)) continue;
    have ??= new Set((typeof loaded === 'function' ? loaded() : loaded) ?? []);
    if (have.has(d.skill)) continue;
    seen.add(d.skill);
    out.push(d);
  }
=== skill-frontmatter.mjs
// A skill's own declaration: the YAML frontmatter at the top of its SKILL.md, read
// for the fields the corpus acts on — `name`, `description` (what the harness
// matches a session's activity against) and, under `metadata`, the corpus's own
// `force-load-on-file-edits-paths`: the files a file tool may touch only with this
// skill loaded (the PreToolUse guard holds the edit until it is). `metadata` is the
// map the harness reserves for a reader's own keys and never acts on, which is why
// the scope lives there and not in the harness's `paths` — that field LIMITS when
// the harness offers a skill, and a skill forced for some files is often wanted
// elsewhere too. The rest of the frontmatter is the harness's business.
//
// A deliberate subset of YAML, never a general parser: `key: scalar`, a block list
// under a key (`- item`), one level of nested map under a key, quoted or bare
// scalars, and a comma-separated scalar where a list is expected. Anything else is
// left unread, and a file with no frontmatter — or a malformed one — reads as a skill
// with empty metadata, which is what the harness does with it too.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

export const FORCE_LOAD_KEY = 'force-load-on-file-edits-paths';
// The other three moments a skill may force itself for, under `metadata` too:
// a tool call, an owner prompt, a tool result. An entry is one scalar — single-
// quote it in the frontmatter, since a regex carries backslashes:
//   force-load-on-tool-calls:          - 'mcp__github__create_pull_request'
//                                      - 'Bash.command /(^|[;&|]\\s*)git\\s+commit\\b/'
//   force-load-on-prompts-matching:    - '/\\bLGTM\\b/'
//   force-load-on-tool-results-matching: - 'WebFetch /EGRESS_BLOCKED|\\b403\\b/'
// A tool entry is the tool's exact name — optionally `.field`, the input field
// the regex reads (`Bash.command`) — or a /regex/ over names, then optionally a
// space and a /regex/ over that field, or over the whole input (or the result)
// serialized as JSON when no field is named.
export const TOOL_CALL_KEY = 'force-load-on-tool-calls';
export const PROMPT_KEY = 'force-load-on-prompts-matching';
export const TOOL_RESULT_KEY = 'force-load-on-tool-results-matching';

const RE_FORM = /^\/(.*)\/([a-z]*)$/s;
const toRegExp = (s) => { const m = RE_FORM.exec(String(s).trim()); try { return m ? new RegExp(m[1], m[2]) : null; } catch { return null; } };
const listAt = (fm, key) => {
  const v = fm?.metadata && typeof fm.metadata === 'object' && !Array.isArray(fm.metadata) ? fm.metadata[key] : undefined;
  return Array.isArray(v) ? v : typeof v === 'string' && v.trim() ? [v] : [];
};

// "<tool>", "<tool>.<field>", either with " /regex/" → { tool (name or RegExp),
// field (a dot path into the input, or null), pattern (RegExp or null), source };
// a malformed entry is null (dropped, never a wedged hook).
export function parseToolTrigger(entry) {
  const m = /^(\/(?:[^/\\]|\\.)*\/[a-z]*|[^\s/][^\s]*)(?:\s+(\/.*\/[a-z]*))?$/s.exec(String(entry).trim());
  if (!m) return null;
  let tool = m[1];
  let field = null;
  if (tool.startsWith('/')) { tool = toRegExp(tool); if (tool === null) return null; }
  else if (tool.includes('.')) { [tool, ...field] = tool.split('.'); field = field.join('.'); }
