// Dry run of the design's `check`, marker form: every rule ends with a marker
// naming a live file, every check/skill/task/pack id names a live file, every
// live file is named by a carrier, and every file parses.
import { readFileSync, readdirSync, existsSync } from 'node:fs';
import { join, basename } from 'node:path';

const [packDir, outDir] = process.argv.slice(2);
const provDir = join(outDir, 'provenance');
const KINDS = new Set(['born','reworded','strengthened','weakened','split','merged','moved','converted','trigger-changed','policy-changed','severity-changed','reaffirmed','promoted','retired']);
const MARKER = /\(([a-z0-9][a-z0-9-]*)\)\s*$/;
const findings = [];
const files = new Map(); // slug -> status
for (const name of readdirSync(provDir).sort()) {
  const text = readFileSync(join(provDir, name), 'utf8');
  if (/^---/.test(text)) findings.push(`${name}: carries a header`);
  if (name === 'declined.md') continue;
  const body = text;
  const heads = [...body.matchAll(/^## (.*)$/gm)].map((x) => x[1]);
  let last = '';
  heads.forEach((h, i) => {
    const hm = h.match(/^(\d{4}-\d{2}-\d{2}) · ([a-z-]+) · (.+)$/);
    if (!hm) { findings.push(`${name}: bad entry heading: ${h}`); return; }
    if (!KINDS.has(hm[2])) findings.push(`${name}: unknown kind ${hm[2]}`);
    if (i === 0 && hm[2] !== 'born') findings.push(`${name}: first entry is ${hm[2]}, not born`);
    if (hm[1] < last) findings.push(`${name}: dates out of order at ${h}`);
    last = hm[1];
    if (['born','converted','moved','trigger-changed','policy-changed','severity-changed'].includes(hm[2])) {
      const entry = body.split(/^## /m)[i + 1];
      if (!/^- \*\*Mechanism:\*\* /m.test(entry)) findings.push(`${name}: ${hm[2]} entry lacks Mechanism`);
    }
  });
  const lastKind = heads.length ? heads[heads.length - 1].split(' · ')[1] : null;
  files.set(name.replace(/\.md$/, ''), lastKind === 'retired' ? 'retired' : 'live');
  if (!heads.length && text.trim() !== '') findings.push(`${name}: not empty but has no entries`);
  if (heads.length) {
    const born = body.split(/^## /m)[1];
    for (const f of ['Actor', 'Landed'])
      if (!new RegExp(`^- \\*\\*${f}:\\*\\* `, 'm').test(born)) findings.push(`${name}: born entry lacks ${f}`);
    for (const m of born.matchAll(/^- \*\*([\w ]+):\*\*/gm)) if (!['Source','Reason','Actor','Model','Mechanism','Rejected','Retire when','Landed'].includes(m[1])) findings.push(`${name}: unknown field ${m[1]}`);
    if (/unrecovered|none recorded/.test(body)) findings.push(`${name}: placeholder value`);
  }
  for (const line of body.split('\n')) if (/^- \*\*/.test(line) && !/^- \*\*[A-Z][\w ]*:\*\* \S/.test(line)) findings.push(`${name}: bad field line: ${line}`);
}
const named = new Set();
const name = (slug, carrier) => { if (files.get(slug) !== 'live') findings.push(`${carrier} names ${slug}.md, which is not a live file`); named.add(slug); };
// rules: from the rendered RULES.md
const lines = readFileSync(join(outDir, 'RULES.md'), 'utf8').split('\n');
let cur = null; const ends = [];
lines.forEach((line, i) => {
  if (/^- /.test(line)) { if (cur) ends.push(cur); cur = { start: i, end: i, text: line }; return; }
  if (cur && /^\s+\S/.test(line)) { cur.end = i; return; }
  if (cur) { ends.push(cur); cur = null; }
});
if (cur) ends.push(cur);
for (const b of ends) {
  const trigger = b.text.match(/^- \*\*(.+?)\*\*/)?.[1];
  if (!trigger) continue;
  const slug = lines[b.end].match(MARKER)?.[1];
  if (!slug) { findings.push(`rule "${trigger}" (line ${b.start + 1}) ends with no marker`); continue; }
  name(slug, `rule "${trigger}"`);
}
name('pack', 'the manifest');
for (const s of existsSync(join(packDir, 'skills')) ? readdirSync(join(packDir, 'skills')) : []) name(s, `skill ${s}`);
for (const dir of ['worldRules', 'workRules']) { const d = join(packDir, dir); if (!existsSync(d)) continue;
  for (const f of readdirSync(d)) { const id = readFileSync(join(d, f), 'utf8').match(/\bid:\s*['"]([^'"]+)['"]/)?.[1]; if (id) name(id.replace(/\//g, '-'), `check ${id}`); } }
if (existsSync(join(packDir, 'declared-checks.json'))) for (const c of JSON.parse(readFileSync(join(packDir, 'declared-checks.json'), 'utf8'))) name(c.id.replace(/\//g, '-'), `check ${c.id}`);
for (const t of existsSync(join(packDir, 'tasks')) ? readdirSync(join(packDir, 'tasks')) : []) name(t, `task ${t}`);
for (const [slug, status] of files) if (status === 'live' && !named.has(slug)) findings.push(`${slug}.md is live but no carrier names it`);
if (findings.length) { console.log(findings.join('\n')); process.exit(1); }
console.log(`ok: ${named.size} live element files, each named by a carrier; every rule marked`);
